import type { Metadata } from "next";
import Link from "next/link";
import {
  Bricolage_Grotesque,
  Google_Sans_Flex,
  Host_Grotesk,
} from "next/font/google";
import { ThemeProvider } from "next-themes";
import { BodyText, TitleText } from "@dooph-software/design-system";
import { ThemeToggle } from "@/components/theme-toggle";
import "./globals.css";

const googleSansFlex = Google_Sans_Flex({
  subsets: ["latin"],
  variable: "--font-google-sans-flex",
  display: "swap",
  axes: ["GRAD", "ROND", "wdth"],
});

const hostGrotesk = Host_Grotesk({
  subsets: ["latin"],
  weight: ["400", "500", "600"],
  variable: "--font-host-grotesk",
  display: "swap",
});

const bricolageGrotesque = Bricolage_Grotesque({
  subsets: ["latin"],
  variable: "--font-bricolage-grotesque",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Acme",
  description: "Acme helps teams ship together.",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang="en"
      className={`${googleSansFlex.variable} ${hostGrotesk.variable} ${bricolageGrotesque.variable} antialiased`}
      suppressHydrationWarning
    >
      <body>
        <ThemeProvider attribute="class" defaultTheme="system" enableSystem>
          <header className="flex items-center justify-between gap-md border-b border-border-primary px-xl py-md">
            <Link href="/">
              <TitleText>Acme</TitleText>
            </Link>
            <nav className="flex items-center gap-lg">
              <Link href="/" className="text-text-secondary hover:text-text">
                <BodyText>Home</BodyText>
              </Link>
              <Link href="/dashboard" className="text-text-secondary hover:text-text">
                <BodyText>Dashboard</BodyText>
              </Link>
              <ThemeToggle />
            </nav>
          </header>
          {children}
        </ThemeProvider>
      </body>
    </html>
  );
}

